function formatCount(count: number | null): string {
  if (!count) return 'none';
  return `${count} items`;
}

console.log(formatCount(0));

type State =
  | { status: 'idle' }
  | { status: 'success'; data: string[] }
  | { status: 'error'; message: string };

function label(state: State): string {
  switch (state.status) {
    case 'idle':
      return 'Not loaded';
    case 'success':
      return `${state.data.length} found`;
    case 'error':
      return state.message;
  }
}

console.log(label({ status: 'success', data: ['a', 'b'] }), label({ status: 'error', message: 'Offline' }));
